function getOptionsByPath(options, path) {
    // Split the path into individual key segments
    const segments = path.split('.');

    // Use reduce to traverse the object, matching each segment to its corresponding property
    return segments.reduce((accumulator, currentSegment) => {
        if (!accumulator[currentSegment]) {
            return accumulator; // If the current segment is not found, return the existing state
        }

        // Recursively call the function for the next segment
        return {...accumulator, ...getOptionsByPath(accumulator[currentSegment], currentSegment)};
    }, {});
}

